      "sourceId": "casler2019-golgi-cargo",
      "studyType": "primary-experiment",
      "doi": "10.1083/jcb.201807195",
      "journal": "Journal of Cell Biology",
      "volume": "218",
      "issue": "5",
      "pages": "1582-1601",
      "system": "Cargo persistence during changing yeast Golgi identity",
      "preparation": "Track individual source yeast Golgi cisternae by three-color 4D confocal microscopy after release of engineered fluorescent cargo, using early Vrg4 and late Sec7 markers. The ordinary maturation observations are kept separate from nocodazole-treated daughter-cell FRAP experiments.",
      "observable": "Resident-marker exchange and fluorescence of cargo in a tracked cisterna.",
      "finding": "Individual source cisternae lose early Vrg4, acquire late Sec7 and subsequently lose Sec7 over approximately three minutes, while cargo remains visible through maturation. Functional compartment organization does not require immutable molecular membership. Across 19 aligned source maturation events, cargo fluorescence transiently increases by approximately 70% during the early-to-late transition. This intensity result motivates an exchange interpretation but is not by itself direct counting of transported molecules.",
      "limitations": [
        "A tracked fluorescence-labeled cisterna is a source-specific dynamic compartment, not proof that all eukaryotic organelles are permanently stable objects.",
        "Marker identity, cargo intensity and actual membrane topology have different measurement limits. No direct tracking of every cargo molecule or every carrier is supplied.",
        "The cargo is engineered, the yeast Golgi is spatially resolvable and nonstacked, and the strain is modified; no universal maturation time is inferred.",
        "The 19 events are measurements within one publication, not independent studies. The source simulation is derivative and was not replayed."
      ],
      "readExtent": "selected-primary-results-discussion-microscopy-immunoblot-methods-captions",
      "reviewedLocators": [
        "JCB 218(5),1582-1601, Results Visualizing the behavior of the secretory cargo during Golgi maturation; Figure 6A-C; Discussion; Methods Fluorescence microscopy and FRAP"
      ],
