        "The proposed recycling direction and carrier identity combine timing, genetics and a source model. Raw movies, per-carrier cargo tracing and simulation were not replayed.",
        "The source tested a specific glycosylation variant; broad protein-quality-control function is a hypothesis requiring further work."
