        "Early Rab5 endosomes are not all endosomes; the source explicitly leaves late/recycling compartments for future work.",
        "This spatial dataset is related to the same-paper ER motility and treatment data. No inherited arrangement, polarity-generation mechanism or all-protein distribution law was tested."
